;; A = slot index 0..7 : HL = sha_v + A*16
sha_vaddr:
        and     #7
        swap    a               ; *16, safe because A <= 7
        ld      l,a
        ld      h,#0
        ld      de,#_sha_v
        add     hl,de
        ret

;; A = word index 0..15 : HL = sha_w + A*16
sha_waddr:
        and     #15
        swap    a               ; *16, safe because A <= 15
        ld      l,a
        ld      h,#0
        ld      de,#_sha_w
        add     hl,de
        ret

;; A = k : HL = sha_v + ((base + k) & 7) * 16
sha_slot:
        ld      hl,#sha_base
        add     a,(hl)
        jp      sha_vaddr

