;; A = round number : HL = sha_k + A*8
sha_kaddr:
        ld      h,#0
        ld      l,a
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; *8
        ld      de,#sha_k
        add     hl,de
        ret

;; ------------------------------------------------------------- block
;; void sha512_block_asm(void): hashes the 128 bytes at _sha_src into the
;; eight words at _sha_h.
_sha512_block_asm::
        push    bc

;; W[i] = the i-th big-endian word of the input, then mirrored
        xor     a
        ld      (sha_i),a
wload:
        ld      a,(sha_i)
        call    sha_waddr
        ld      d,h
        ld      e,l             ; DE = &W[i]
        ld      a,(sha_i)
        ld      h,#0
        ld      l,a
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; i*8
        ld      a,(#_sha_src)
        ld      c,a
        ld      a,(#_sha_src+1)
        ld      b,a
        add     hl,bc
        ld      bc,#7
        add     hl,bc           ; HL = src + i*8 + 7, the low byte first
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(hl-)
        ld      (de),a
        inc     de
        ld      a,(sha_i)
        call    sha_waddr
        call    sha_mir8
        ld      hl,#sha_i
        inc     (hl)
        ld      a,(hl)
        cp      #16
        jr      nz,wload

;; v[k] = h[k], doubled
        xor     a
        ld      (sha_i),a
vload:
        ld      a,(sha_i)
        call    sha_vaddr
        push    hl
        ld      a,(sha_i)
        ld      h,#0
        ld      l,a
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; k*8
        ld      a,(#_sha_h)
        ld      c,a
        ld      a,(#_sha_h+1)
        ld      b,a
        add     hl,bc
        ld      d,h
        ld      e,l
        pop     hl
        call    sha_cpy8
        ld      a,(sha_i)
        call    sha_vaddr
        call    sha_mir8
        ld      hl,#sha_i
        inc     (hl)
        ld      a,(hl)
        cp      #8
        jr      nz,vload

        xor     a
        ld      (sha_base),a
        ld      (sha_i),a

round:
        ld      a,(sha_i)
        cp      #16
        jp      c,no_sched

;; ---- message schedule: W[j] += sigma0(W[j+1]) + W[j+9] + sigma1(W[j+14])
;; sigma0(x) = rotr1(x) ^ rotr8(x) ^ shr7(x)
        ld      hl,#_sha_s0
        push    hl
        ld      a,(sha_i)
        add     a,#1
        call    sha_waddr
        pop     de
        call    sha_rot1
        ld      hl,#sha_tm
        push    hl
        ld      a,(sha_i)
        add     a,#1
        call    sha_waddr
        ld      a,l
        add     a,#1
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot0
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s0
        pop     de
        call    sha_xor8
        ld      hl,#sha_tm
        push    hl
        ld      a,(sha_i)
        add     a,#1
        call    sha_waddr
        pop     de
        call    sha_shr7
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s0
        pop     de
        call    sha_xor8
;; sigma1(y) = rotr19(y) ^ rotr61(y) ^ shr6(y)
        ld      hl,#_sha_s1
        push    hl
        ld      a,(sha_i)
        add     a,#14
        call    sha_waddr
        ld      a,l
        add     a,#2
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot3
        ld      hl,#sha_tm
        push    hl
        ld      a,(sha_i)
        add     a,#14
        call    sha_waddr
        ld      a,l
        add     a,#7
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot5
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s1
        pop     de
        call    sha_xor8
        ld      hl,#sha_tm
        push    hl
        ld      a,(sha_i)
        add     a,#14
        call    sha_waddr
        pop     de
        call    sha_shr6
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s1
        pop     de
        call    sha_xor8
;; W[j] += s0 + W[j+9] + s1, then refresh the mirrored copy
        ld      hl,#_sha_s0
        push    hl
        ld      a,(sha_i)
        call    sha_waddr
        pop     de
        call    sha_add8
        ld      a,(sha_i)
        add     a,#9
        call    sha_waddr
        push    hl
        ld      a,(sha_i)
        call    sha_waddr
        pop     de
        call    sha_add8
        ld      hl,#_sha_s1
        push    hl
        ld      a,(sha_i)
        call    sha_waddr
        pop     de
        call    sha_add8
        ld      a,(sha_i)
        call    sha_waddr
        call    sha_mir8

no_sched:
;; ---- Sum1(e) = rotr14 ^ rotr18 ^ rotr41,  e = slot 4
        ld      hl,#_sha_s1
        push    hl
        ld      a,#4
        call    sha_slot
        ld      a,l
        add     a,#1
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot6
        ld      hl,#sha_tm
        push    hl
        ld      a,#4
        call    sha_slot
        ld      a,l
        add     a,#2
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot2
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s1
        pop     de
        call    sha_xor8
        ld      hl,#sha_tm
        push    hl
        ld      a,#4
        call    sha_slot
        ld      a,l
        add     a,#5
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot1
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s1
        pop     de
        call    sha_xor8

;; ---- Ch(e,f,g) = g ^ (e & (f ^ g))
        ld      a,#5
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_cpy8
        ld      a,#6
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_xor8
        ld      a,#4
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_and8
        ld      a,#6
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_xor8

;; ---- T1 = h + Sum1 + Ch + K[i] + W[j]
        ld      a,#7
        call    sha_slot
        push    hl
        ld      hl,#_sha_t1
        pop     de
        call    sha_cpy8
        ld      hl,#_sha_s1
        push    hl
        ld      hl,#_sha_t1
        pop     de
        call    sha_add8
        ld      hl,#_sha_x
        push    hl
        ld      hl,#_sha_t1
        pop     de
        call    sha_add8
        ld      a,(sha_i)
        call    sha_kaddr
        push    hl
        ld      hl,#_sha_t1
        pop     de
        call    sha_add8
        ld      a,(sha_i)
        call    sha_waddr
        push    hl
        ld      hl,#_sha_t1
        pop     de
        call    sha_add8

;; ---- Sum0(a) = rotr28 ^ rotr34 ^ rotr39,  a = slot 0
        ld      hl,#_sha_s0
        push    hl
        ld      a,#0
        call    sha_slot
        ld      a,l
        add     a,#3
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot4
        ld      hl,#sha_tm
        push    hl
        ld      a,#0
        call    sha_slot
        ld      a,l
        add     a,#4
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot2
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s0
        pop     de
        call    sha_xor8
        ld      hl,#sha_tm
        push    hl
        ld      a,#0
        call    sha_slot
        ld      a,l
        add     a,#4
        ld      l,a
        ld      a,h
        adc     a,#0
        ld      h,a
        pop     de
        call    sha_rot7
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_s0
        pop     de
        call    sha_xor8

;; ---- Maj(a,b,c) = ((a ^ b) & (b ^ c)) ^ b
        ld      a,#0
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_cpy8
        ld      a,#1
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_xor8
        ld      a,#1
        call    sha_slot
        push    hl
        ld      hl,#sha_tm
        pop     de
        call    sha_cpy8
        ld      a,#2
        call    sha_slot
        push    hl
        ld      hl,#sha_tm
        pop     de
        call    sha_xor8
        ld      hl,#sha_tm
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_and8
        ld      a,#1
        call    sha_slot
        push    hl
        ld      hl,#_sha_x
        pop     de
        call    sha_xor8

;; ---- T2 = Sum0 + Maj, kept in sha_s0
        ld      hl,#_sha_x
        push    hl
        ld      hl,#_sha_s0
        pop     de
        call    sha_add8

;; ---- the only two writes: d += T1 becomes the next e ...
        ld      hl,#_sha_t1
        push    hl
        ld      a,#3
        call    sha_slot
        pop     de
        call    sha_add8
        ld      a,#3
        call    sha_slot
        call    sha_mir8
;; ... and T1 + T2 lands in h's slot, becoming the next a
        ld      hl,#_sha_t1
        push    hl
        ld      a,#7
        call    sha_slot
        pop     de
        call    sha_cpy8
        ld      hl,#_sha_s0
        push    hl
        ld      a,#7
        call    sha_slot
        pop     de
        call    sha_add8
        ld      a,#7
        call    sha_slot
        call    sha_mir8

;; rotate the slots: a moves one place back
        ld      hl,#sha_base
        ld      a,(hl)
        dec     a
        and     #7
        ld      (hl),a

        ld      hl,#sha_i
        inc     (hl)
        ld      a,(hl)
        ld      hl,#_sha_rounds
        cp      (hl)
        jp      nz,round

;; h[k] += v[(base + k) & 7]
        xor     a
        ld      (sha_i),a
hstore:
        ld      a,(sha_i)
        ld      h,#0
        ld      l,a
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; k*8
        ld      a,(#_sha_h)
        ld      c,a
        ld      a,(#_sha_h+1)
        ld      b,a
        add     hl,bc           ; HL = &h[k]
        push    hl
        ld      a,(sha_i)
        call    sha_slot        ; DE = &v[(base+k)&7]
        ld      d,h
        ld      e,l
        pop     hl
        call    sha_add8
        ld      hl,#sha_i
        inc     (hl)
        ld      a,(hl)
        cp      #8
        jr      nz,hstore

        pop     bc
        ret
